var t=[{title:`Vad varje område gör`,text:`Bröstryggen är den mittersta delen av ryggen, och den låter dig rotera och sträcka ut. Axelkomplexet inkluderar kulleden och skulderbladet som glider över bröstkorgen. Att sträcka sig över huvudet beror på att flera områden arbetar tillsammans, så det testar mer än flexibiliteten i axelleden.`},{title:`Utforska bekväm rörelse`,text:`En övning med öppen bok vrider försiktigt överkroppen medan höfterna förblir ganska stilla. Kontrollerade armcirklar övar axelrörelse, och katt-ko rör ryggraden genom flexion och extension i lugnt tempo. Rör dig långsamt, andas normalt och tvinga inte slutläget.`},{title:`Rörlighet i dina lyft`,text:`Press över huvudet kan kännas mjukare när revbenen, skulderbladen och armarna rör sig tillsammans. Vid rodd, låt skulderbladen röra sig naturligt. Du behöver inte hålla dem fastlåsta bakåt hela tiden. Sikta på mjuk kontroll i den övning du valt. Det finns ingen enskild stel hållning som alla måste kopiera.`},{title:`Rörlighet plus styrka`,text:`Lätta pressar, väggglid, rodd och kontrollerade bärande bygger användbart omfång och koordination tillsammans. Enbart stretching kan förbättra passiv flexibilitet utan att ge dig full kontroll under belastning. Om en övning känns instabil eller obekväm, ändra greppet, vinkeln eller rörelseomfånget.`},{title:`Så använder du TrainUp`,text:`Om arbete över huvudet stör din axel, lägg till axeln som en begränsning i Profil, med en anteckning. Programmet väljer bara övningar som passar dina begränsningar. Vid ny, ihållande eller förvärrad axelsmärta, träffa en läkare eller fysioterapeut i stället för att förlita dig på allmänna rörlighetsövningar.`}];var n=[{label:`ACE 2026: rörlighet jämfört med flexibilitet`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: praktisk vägledning om stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};